"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[1212],{28528:e=>{e.exports=JSON.parse('{"functions":[{"name":"new","desc":"Creates a new `GenericPoolObject` pool.\\n\\n`objectClass` must be a table with a `new` function.  `objectInput` is\\neither an array of constructor arguments (passed via `table.unpack`) or a\\ncloneable `Instance` template.","params":[{"name":"objectClass","desc":"Class with a `new` constructor. Defaults to `Instance`.","lua_type":"{new: (...any) -> any}?"},{"name":"objectInput","desc":"Constructor args array, or a cloneable Instance template. Defaults to `{\\"Part\\"}`.","lua_type":"({any} | Instance)?"},{"name":"initialSize","desc":"Number of objects to pre-allocate. Defaults to `0`.","lua_type":"number?"},{"name":"maxSize","desc":"Hard cap on pool size (`-1` = unlimited). Defaults to `-1`.","lua_type":"number?"},{"name":"expandSize","desc":"How many objects to create when the pool is exhausted. Defaults to `50`.","lua_type":"number?"},{"name":"insertFunction","desc":"Optional callback invoked each time a new object is created.","lua_type":"((any) -> ())?"}],"returns":[{"desc":"","lua_type":"GenericPoolObject"}],"function_type":"static","tags":["constructor"],"source":{"line":171,"path":"src/ReplicatedStorage/SharedModules/GenericPoolObject.luau"}},{"name":"SetMaxSize","desc":"Sets the maximum pool size.  If the pool currently holds more objects than\\nthe new cap, the excess are destroyed (when destroyable) and removed.\\nPass `-1` for unlimited.","params":[{"name":"maxSize","desc":"New cap. `-1` = unlimited.","lua_type":"number?"}],"returns":[{"desc":"Returns `self` for chaining.","lua_type":"GenericPoolObject"}],"function_type":"method","source":{"line":234,"path":"src/ReplicatedStorage/SharedModules/GenericPoolObject.luau"}},{"name":"SetInsertFunction","desc":"Replaces the pool\'s `insertFunction`.  When `applyFunction` is `true` the\\nnew callback is immediately called on every object currently in the pool.","params":[{"name":"insertFunction","desc":"New callback, or `nil` to clear.","lua_type":"((any) -> ())?"},{"name":"applyFunction","desc":"When `true`, applies the callback to all existing pooled objects.","lua_type":"boolean?"}],"returns":[{"desc":"Returns `self` for chaining.","lua_type":"GenericPoolObject"}],"function_type":"method","source":{"line":269,"path":"src/ReplicatedStorage/SharedModules/GenericPoolObject.luau"}},{"name":"MakeGlobal","desc":"Registers the pool in the shared `GenericPoolObject.globalPools` registry\\nunder `globalName`.  Any previous registration under a different name is\\ncleared first.","params":[{"name":"globalName","desc":"Key used to look up this pool globally.","lua_type":"string"}],"returns":[{"desc":"Returns `self` for chaining.","lua_type":"GenericPoolObject"}],"function_type":"method","source":{"line":295,"path":"src/ReplicatedStorage/SharedModules/GenericPoolObject.luau"}},{"name":"MakeLocal","desc":"Removes the pool from the global registry.  Has no effect if the pool was\\nnever registered globally.","params":[],"returns":[{"desc":"Returns `self` for chaining.","lua_type":"GenericPoolObject"}],"function_type":"method","source":{"line":314,"path":"src/ReplicatedStorage/SharedModules/GenericPoolObject.luau"}},{"name":"ContainsObject","desc":"Returns whether `object` is currently held inside this pool.","params":[{"name":"object","desc":"The object to search for.","lua_type":"any"}],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"method","source":{"line":330,"path":"src/ReplicatedStorage/SharedModules/GenericPoolObject.luau"}},{"name":"LoadObjects","desc":"Pre-fills the pool by constructing `objectCount` additional objects\\n(capped by `maxSize` when set).","params":[{"name":"objectCount","desc":"Number of new objects to add.","lua_type":"number"}],"returns":[{"desc":"Returns `self` for chaining.","lua_type":"GenericPoolObject"}],"function_type":"method","source":{"line":342,"path":"src/ReplicatedStorage/SharedModules/GenericPoolObject.luau"}},{"name":"InsertObject","desc":"Returns a single externally-owned object back into the pool.  No-ops if\\nthe pool is at capacity.  For parentable objects (`Instance`), clears the\\n`Parent` property.","params":[{"name":"object","desc":"The object to recycle.","lua_type":"any"}],"returns":[{"desc":"Returns `self` for chaining.","lua_type":"GenericPoolObject"}],"function_type":"method","source":{"line":369,"path":"src/ReplicatedStorage/SharedModules/GenericPoolObject.luau"}},{"name":"InsertObjects","desc":"Bulk-recycles an array of externally-owned objects back into the pool.\\nExcess objects beyond `maxSize` are silently dropped.","params":[{"name":"objects","desc":"Array of objects to recycle.","lua_type":"{any}"}],"returns":[{"desc":"Returns `self` for chaining.","lua_type":"GenericPoolObject"}],"function_type":"method","source":{"line":394,"path":"src/ReplicatedStorage/SharedModules/GenericPoolObject.luau"}},{"name":"ReturnObject","desc":"Peeks at the most-recently-added object without removing it from the pool.","params":[],"returns":[{"desc":"The top-of-stack object, or `nil` if the pool is empty.","lua_type":"any?"}],"function_type":"method","source":{"line":428,"path":"src/ReplicatedStorage/SharedModules/GenericPoolObject.luau"}},{"name":"ReturnObjects","desc":"Returns up to `objectCount` objects from the top of the pool stack\\n**without** removing them.  Returns `nil` if the pool is empty.","params":[{"name":"objectCount","desc":"Maximum number of objects to peek at.","lua_type":"number"}],"returns":[{"desc":"Array of objects (newest-first), or `nil`.","lua_type":"{any}?"}],"function_type":"method","source":{"line":440,"path":"src/ReplicatedStorage/SharedModules/GenericPoolObject.luau"}},{"name":"ReturnCustomObject","desc":"Peeks at the most-recently-added object that satisfies `predicate`\\nwithout removing it from the pool.","params":[{"name":"predicate","desc":"Filter function.","lua_type":"(any) -> boolean"}],"returns":[{"desc":"Matching object, or `nil`.","lua_type":"any?"}],"function_type":"method","source":{"line":463,"path":"src/ReplicatedStorage/SharedModules/GenericPoolObject.luau"}},{"name":"ReturnCustomObjects","desc":"Peeks at all pooled objects that satisfy `predicate` without removing\\nthem.  Returns `nil` if none match.","params":[{"name":"predicate","desc":"Filter function.","lua_type":"(any) -> boolean"}],"returns":[{"desc":"Matching objects, or `nil`.","lua_type":"{any}?"}],"function_type":"method","source":{"line":485,"path":"src/ReplicatedStorage/SharedModules/GenericPoolObject.luau"}},{"name":"RemoveObject","desc":"Permanently removes `object` from the pool and destroys it (when\\ndestroyable).","params":[{"name":"object","desc":"The object to remove and destroy.","lua_type":"any"}],"returns":[{"desc":"Returns `self` for chaining.","lua_type":"GenericPoolObject"}],"function_type":"method","source":{"line":509,"path":"src/ReplicatedStorage/SharedModules/GenericPoolObject.luau"}},{"name":"RetrieveObject","desc":"Removes and returns one object from the pool.  If the pool is empty it\\nauto-expands by `expandSize` objects first.","params":[],"returns":[{"desc":"The retrieved object (never `nil`; expands automatically).","lua_type":"any"}],"function_type":"method","source":{"line":531,"path":"src/ReplicatedStorage/SharedModules/GenericPoolObject.luau"}},{"name":"RetrieveObjects","desc":"Removes and returns `objectCount` objects from the pool.  Auto-expands\\nif there are not enough idle objects.","params":[{"name":"objectCount","desc":"Number of objects to retrieve.","lua_type":"number"}],"returns":[{"desc":"Array of retrieved objects.","lua_type":"{any}"}],"function_type":"method","source":{"line":549,"path":"src/ReplicatedStorage/SharedModules/GenericPoolObject.luau"}},{"name":"RetrieveCustomObject","desc":"Removes and returns the first pooled object that satisfies `predicate`,\\nsearching from newest to oldest.  Returns `nil` if nothing matches.","params":[{"name":"predicate","desc":"Filter function.","lua_type":"(any) -> boolean"}],"returns":[{"desc":"The matching object, or `nil`.","lua_type":"any?"}],"function_type":"method","source":{"line":585,"path":"src/ReplicatedStorage/SharedModules/GenericPoolObject.luau"}},{"name":"RetrieveCustomObjects","desc":"Removes and returns all pooled objects that satisfy `predicate`.\\nReturns `nil` if nothing matches.","params":[{"name":"predicate","desc":"Filter function.","lua_type":"(any) -> boolean"}],"returns":[{"desc":"Matching objects, or `nil`.","lua_type":"{any}?"}],"function_type":"method","source":{"line":607,"path":"src/ReplicatedStorage/SharedModules/GenericPoolObject.luau"}},{"name":"Clone","desc":"Creates a new `GenericPoolObject` pool with the same configuration and a\\ncopy of all currently pooled objects.","params":[],"returns":[{"desc":"The cloned pool.","lua_type":"GenericPoolObject"}],"function_type":"method","source":{"line":630,"path":"src/ReplicatedStorage/SharedModules/GenericPoolObject.luau"}},{"name":"Clear","desc":"Destroys all objects currently held in the pool (when destroyable) and\\nempties the pool array.  The pool itself remains usable.","params":[],"returns":[{"desc":"Returns `self` for chaining.","lua_type":"GenericPoolObject"}],"function_type":"method","source":{"line":659,"path":"src/ReplicatedStorage/SharedModules/GenericPoolObject.luau"}},{"name":"Destroy","desc":"Destroys all pooled objects, de-registers the pool from the global\\nregistry, wipes the pool table, and clears the metatable.  The reference\\nshould be discarded afterwards.","params":[],"returns":[],"function_type":"method","source":{"line":677,"path":"src/ReplicatedStorage/SharedModules/GenericPoolObject.luau"}}],"properties":[],"types":[],"name":"GenericPoolObject","desc":"A reusable object pool for arbitrary Luau objects (not limited to Roblox\\n`Instance`s).  Any class that exposes a `new(...)` constructor can be\\npooled \u2014 including plain Luau tables, custom OOP classes, or Roblox\\nInstances created via `Instance.new`.\\n\\nUnlike `GenericPoolInstance`, this variant does not manage `CFrame`\\nteleporting or `Folder` parents.  Recycled objects are simply held in an\\ninternal array and handed back on the next retrieval.\\n\\n```lua\\nlocal GenericPoolObject = require(path.to.GenericPoolObject)\\n\\nlocal pool = GenericPoolObject.new(MyClass, {\\"arg1\\", \\"arg2\\"}, 10)\\nlocal obj  = pool:RetrieveObject()\\n-- ... use obj ...\\npool:InsertObject(obj)\\n```","source":{"line":25,"path":"src/ReplicatedStorage/SharedModules/GenericPoolObject.luau"}}')}}]);